-- Link every product row (incl. dose/size variants) to its canonical compound.
-- Stacks are matched first so combo rows are not captured by single-compound matches.
update public.products set compound_slug='bpc-tb'        where name ilike 'BPC%' and name ilike '%TB%';
update public.products set compound_slug='cjc-ipamorelin' where name ilike 'CJC%' and (name ilike '%IPA%' or name ilike '%ipamorelin%');
update public.products set compound_slug='glow'          where name ilike 'GLOW%';
update public.products set compound_slug='klow'          where name ilike 'KLOW%';
update public.products set compound_slug='cagrisema'     where name ilike 'Cagrilintide%' and name ilike '%Semaglutide%';

update public.products set compound_slug='epithalon'            where compound_slug is null and name ilike 'Epithalon%';
update public.products set compound_slug='foxo4-dri'            where compound_slug is null and name ilike 'FOXO4%';
